+
+// ValueScanMutation represents an operation that mutates the ValueScan nodes in the graph.
+type ValueScanMutation struct {
+	config
+	op            Op
+	typ           string
+	id            *schema.ValueScanID
+	name          *string
+	clearedFields map[string]struct{}
+	done          bool
+	oldValue      func(context.Context) (*ValueScan, error)
+	predicates    []predicate.ValueScan
+}
+
+var _ ent.Mutation = (*ValueScanMutation)(nil)
+
+// valuescanOption allows management of the mutation configuration using functional options.
+type valuescanOption func(*ValueScanMutation)
+
+// newValueScanMutation creates new mutation for the ValueScan entity.
+func newValueScanMutation(c config, op Op, opts ...valuescanOption) *ValueScanMutation {
+	m := &ValueScanMutation{
+		config:        c,
+		op:            op,
+		typ:           TypeValueScan,
+		clearedFields: make(map[string]struct{}),
+	}
+	for _, opt := range opts {
+		opt(m)
+	}
+	return m
+}
+
+// withValueScanID sets the ID field of the mutation.
+func withValueScanID(id schema.ValueScanID) valuescanOption {
+	return func(m *ValueScanMutation) {
+		var (
+			err   error
+			once  sync.Once
+			value *ValueScan
+		)
+		m.oldValue = func(ctx context.Context) (*ValueScan, error) {
+			once.Do(func() {
+				if m.done {
+					err = errors.New(""querying old values post mutation is not allowed"")
+				} else {
+					value, err = m.Client().ValueScan.Get(ctx, id)
+				}
+			})
+			return value, err
+		}
+		m.id = &id
+	}
+}
+
+// withValueScan sets the old ValueScan of the mutation.
+func withValueScan(node *ValueScan) valuescanOption {
+	return func(m *ValueScanMutation) {
+		m.oldValue = func(context.Context) (*ValueScan, error) {
+			return node, nil
+		}
+		m.id = &node.ID
+	}
+}
+
+// Client returns a new `ent.Client` from the mutation. If the mutation was
+// executed in a transaction (ent.Tx), a transactional client is returned.
+func (m ValueScanMutation) Client() *Client {
+	client := &Client{config: m.config}
+	client.init()
+	return client
+}
+
+// Tx returns an `ent.Tx` for mutations that were executed in transactions;
+// it returns an error otherwise.
+func (m ValueScanMutation) Tx() (*Tx, error) {
+	if _, ok := m.driver.(*txDriver); !ok {
+		return nil, errors.New(""ent: mutation is not running in a transaction"")
+	}
+	tx := &Tx{config: m.config}
+	tx.init()
+	return tx, nil
+}
+
+// SetID sets the value of the id field. Note that this
+// operation is only accepted on creation of ValueScan entities.
+func (m *ValueScanMutation) SetID(id schema.ValueScanID) {
+	m.id = &id
+}
+
+// ID returns the ID value in the mutation. Note that the ID is only available
+// if it was provided to the builder or after it was returned from the database.
+func (m *ValueScanMutation) ID() (id schema.ValueScanID, exists bool) {
+	if m.id == nil {
+		return
+	}
+	return *m.id, true
+}
+
+// IDs queries the database and returns the entity ids that match the mutation's predicate.
+// That means, if the mutation is applied within a transaction with an isolation level such
+// as sql.LevelSerializable, the returned ids match the ids of the rows that will be updated
+// or updated by the mutation.
+func (m *ValueScanMutation) IDs(ctx context.Context) ([]schema.ValueScanID, error) {
+	switch {
+	case m.op.Is(OpUpdateOne | OpDeleteOne):
+		id, exists := m.ID()
+		if exists {
+			return []schema.ValueScanID{id}, nil
+		}
+		fallthrough
+	case m.op.Is(OpUpdate | OpDelete):
+		return m.Client().ValueScan.Query().Where(m.predicates...).IDs(ctx)
+	default:
+		return nil, fmt.Errorf(""IDs is not allowed on %s operations"", m.op)
+	}
+}
+
+// SetName sets the ""name"" field.
+func (m *ValueScanMutation) SetName(s string) {
+	m.name = &s
+}
+
+// Name returns the value of the ""name"" field in the mutation.
+func (m *ValueScanMutation) Name() (r string, exists bool) {
+	v := m.name
+	if v == nil {
+		return
+	}
+	return *v, true
+}
+
+// OldName returns the old ""name"" field's value of the ValueScan entity.
+// If the ValueScan object wasn't provided to the builder, the object is fetched from the database.
+// An error is returned if the mutation operation is not UpdateOne, or the database query fails.
+func (m *ValueScanMutation) OldName(ctx context.Context) (v string, err error) {
+	if !m.op.Is(OpUpdateOne) {
+		return v, errors.New(""OldName is only allowed on UpdateOne operations"")
+	}
+	if m.id == nil || m.oldValue == nil {
+		return v, errors.New(""OldName requires an ID field in the mutation"")
+	}
+	oldValue, err := m.oldValue(ctx)
+	if err != nil {
+		return v, fmt.Errorf(""querying old value for OldName: %w"", err)
+	}
+	return oldValue.Name, nil
+}
+
+// ResetName resets all changes to the ""name"" field.
+func (m *ValueScanMutation) ResetName() {
+	m.name = nil
+}
+
+// Where appends a list predicates to the ValueScanMutation builder.
+func (m *ValueScanMutation) Where(ps ...predicate.ValueScan) {
+	m.predicates = append(m.predicates, ps...)
+}
+
+// WhereP appends storage-level predicates to the ValueScanMutation builder. Using this method,
+// users can use type-assertion to append predicates that do not depend on any generated package.
+func (m *ValueScanMutation) WhereP(ps ...func(*sql.Selector)) {
+	p := make([]predicate.ValueScan, len(ps))
+	for i := range ps {
+		p[i] = ps[i]
+	}
+	m.Where(p...)
+}
+
+// Op returns the operation name.
+func (m *ValueScanMutation) Op() Op {
+	return m.op
+}
+
+// SetOp allows setting the mutation operation.
+func (m *ValueScanMutation) SetOp(op Op) {
+	m.op = op
+}
+
+// Type returns the node type of this mutation (ValueScan).
+func (m *ValueScanMutation) Type() string {
+	return m.typ
+}
+
+// Fields returns all fields that were changed during this mutation. Note that in
+// order to get all numeric fields that were incremented/decremented, call
+// AddedFields().
+func (m *ValueScanMutation) Fields() []string {
+	fields := make([]string, 0, 1)
+	if m.name != nil {
+		fields = append(fields, valuescan.FieldName)
+	}
+	return fields
+}
+
+// Field returns the value of a field with the given name. The second boolean
+// return value indicates that this field was not set, or was not defined in the
+// schema.
+func (..."", ""docs_before_excerpt"": ""<!-- doc/website/blog/2021-07-29-generate-a-fully-working-go-crud-http-api-with-ent.md @ d056659140fa66973dd3753fead00a35de868ca3 -->
---
title: Generate a fully-working Go CRUD HTTP API with Ent
author: MasseElch
authorURL: ""https://github.com/masseelch""
authorImageURL: ""https://avatars.githubusercontent.com/u/12862103?v=4""
---

When we say that one of the core principles of Ent is ""Schema as Code"", we mean by that more than ""Ent's DSL for
defining entities and their edges is done using regular Go code"". Ent's unique approach, compared to many other ORMs, is
to express all of the logic related to an entity, as code, directly in the schema definition.

With Ent, developers can write all authorization logic (called ""[Privacy](https://entgo.io/docs/privacy)"" within Ent),
and all of the mutation side-effects (called ""[Hooks](https://entgo.io/docs/hooks)"" within Ent) directly on the schema.
Having everything in the same place can be very convenient, but its true power is revealed when paired with code
generation.

If schemas are defined this way, it becomes possible to generate code for fully-working production-grade servers
automatically. If we move the responsibility for authorization decisions and custom side effects from the RPC layer to
the data layer, the implementation of the basic CRUD (Create, Read, Update and Delete) endpoints becomes generic to the
extent that it can be machine-generated. This is exactly the idea behind the popular GraphQL and gRPC Ent extensions.

Today, we would like to present a new Ent extension named `elk` that can automatically generate fully-working, RESTful
API endpoints from your Ent schemas. `elk` strives to automate all of the tedious work of setting up the basic CRUD
endpoints for every entity you add to your graph, including logging, validation of the request body, eager loading
relations and serializing, all while leaving reflection out of sight and maintaining type-safety.

Let’s get started!

### Getting Started

The final version of the code below can be found on [GitHub](https://github.com/masseelch/elk-example).

Start by creating a new Go project:

```shell
mkdir elk-example
cd elk-example
go mod init elk-example
```

Invoke the ent code generator and create two schemas: User, Pet:

```shell
go run -mod=mod entgo.io/ent/cmd/ent new Pet User
```

Your project should now look like this:

```
.
├── ent
│   ├── generate.go
│   └── schema
│       ├── pet.go
│       └── user.go
├── go.mod
└── go.sum
```

Next, add the `elk` package to our project:

```shell
go get -u github.com/masseelch/elk
```

`elk` uses the
Ent [extension API](https://github.com/ent/ent/blob/a19a89a141cf1a5e1b38c93d7898f218a1f86c94/entc/entc.go#L197) to
integrate with Ent’s code-generation. This requires that we use the `entc` (ent codegen) package as
described [here](https://entgo.io/docs/code-gen#use-entc-as-a-package). Follow the next three steps to enable it and to
configure Ent to work with the `elk` extension:

1\. Create a new Go file named `ent/entc.go` and paste the following content:

```go
// +build ignore

package main

import (
	""log""

	""entgo.io/ent/entc""
	""entgo.io/ent/entc/gen""
	""github.com/masseelch/elk""
)

func main() {
	ex, err := elk.NewExtension(
		elk.GenerateSpec(""openapi.json""),
		elk.GenerateHandlers(),
	)
	if err != nil {
		log.Fatalf(""creating elk extension: %v"", err)
	}
	err = entc.Generate(""./schema"", &gen.Config{}, entc.Extensions(ex))
	if err != nil {
		log.Fatalf(""running ent codegen: %v"", err)
	}
}

```

2\. Edit the `ent/generate.go` file to execute the `ent/entc.go` file:

```go
package ent

//go:generate go run -mod=mod entc.go

```

3/. `elk` uses some external packages in its generated code. Currently, you have to get those packages manually once
when setting up `elk`:

```shell
go get github.com/mailru/easyjson github.com/masseelch/render github.com/go-chi/chi/v5 go.uber.org/zap
```

With these steps complete, all is set up for using our `elk`-powered ent! To learn more about Ent, how to connect to
different types of databases, run migrations or work with entities head over to
the [Setup Tutorial](https://entgo.io/docs/tutorial-setup/).

### Generating HTTP CRUD Handlers with `elk`

To generate the fully-working HTTP handlers we need first create an Ent schema definition. Open and
edit `ent/schema/pet.go`:

```go
package schema

import (
	""entgo.io/ent""
	""entgo.io/ent/schema/field""
)

// Pet holds the schema definition for the Pet entity.
type Pet struct {
	ent.Schema
}

// Fields of the Pet.
func (Pet) Fields() []ent.Field {
	return []ent.Field{
		field.String(""name""),
		field.Int(""age""),
	}
}

```

We added two fields to our `Pet` entity: `name` and `age`. The `ent.Schema` just defines the fields of our entity. To
generate runnable code from our schema, run:

```shell
go generate ./...
```

Observe that in addition to the files Ent would normally generate, another directory named `ent/http` was created. These
files were generated by the `elk` extension and contain the code for the generated HTTP handlers. For example, here
is some of the generated code for a read-operation on the Pet entity:

```go
const (
	PetCreate Routes = 1 << iota
	PetRead
	PetUpdate
	PetDelete
	PetList
	PetRoutes = 1<<iota - 1
)

// PetHandler handles http crud operations on ent.Pet.
type PetHandler struct {
	handler

	client *ent.Client
	log    *zap.Logger
}

func NewPetHandler(c *ent.Client, l *zap.Logger) *PetHandler {
	return &PetHandler{
		client: c,
		log:    l.With(zap.String(""handler"", ""PetHandler"")),
	}
}

// Read fetches the ent.Pet identified by a given url-parameter from the
// database and renders it to the client.
func (h *PetHandler) Read(w http.ResponseWriter, r *http.Request) {
	l := h.log.With(zap.String(""method"", ""Read""))
	// ID is URL parameter.
	id, err := strconv.Atoi(chi.URLParam(r, ""id""))
	if err != nil {
		l.Error(""error getting id from url parameter"", zap.String(""id"", chi.URLParam(r, ""id"")), zap.Error(err))
		render.BadRequest(w, r, ""id must be an integer greater zero"")
		return
	}
	// Create the query to fetch the Pet
	q := h.client.Pet.Query().Where(pet.ID(id))
	e, err := q.Only(r.Context())
	if err != nil {
		switch {
		case ent.IsNotFound(err):
			msg := stripEntError(err)
			l.Info(msg, zap.Error(err), zap.Int(""id"", id))
			render.NotFound(w, r, msg)
		case ent.IsNotSingular(err):
			msg := stripEntError(err)
			l.Error(msg, zap.Error(err), zap.Int(""id"", id))
			render.BadRequest(w, r, msg)
		default:
			l.Error(""could not read pet"", zap.Error(err), zap.Int(""id"", id))
			render.InternalServerError(w, r, nil)
		}
		return
	}
	l.Info(""pet rendered"", zap.Int(""id"", id))
	easyjson.MarshalToHTTPResponseWriter(NewPet2657988899View(e), w)
}

```

Next, let’s see how to create an actual RESTful HTTP server that can manage your Pet entities. Create a file
named `main.go` and add the following content:

```go
package main

import (
	""context""
	""fmt""
	""log""
	""net/http""

	""elk-example/ent""
	elk ""elk-example/ent/http""

	""github.com/go-chi/chi/v5""
	_ ""github.com/mattn/go-sqlite3""
	""go.uber.org/zap""
)

func main() {
	// Create the ent client.
	c, err := ent.Open(""sqlite3"", ""./ent.db?_fk=1"")
	if err != nil {
		log.Fatalf(""failed opening connection to sqlite: %v"", err)
	}
	defer c.Close()
	// Run the auto migration tool.
	if err := c.Schema.Create(context.Background()); err != nil {
		log.Fatalf(""failed creating schema resources: %v"", err)
	}
	// Router and Logger.
	r, l := chi.NewRouter(), zap.NewExample()
	// Create the pet handler.
	r.Route(""/pets"", func(r chi.Router) {
		elk.NewPetHandler(c, l).Mount(r, elk.PetRoutes)
	})
	// Start listen to incoming requests.
	fmt.Println(""Server running"")
	defer fmt.Println(""Server stopped"")
	if err := http.ListenAndServe("":8080"", r); err != nil {
		log.Fatal(err)
	}
}

```

Next, start the server:

```shell
go run -mod=mod main.go
```

Congratulations! We now have a running server serving the Pets API. We could ask the server for a list of all pets in
the database, but there are none yet. Let’s create one first:

```shell
curl -X 'POST' -H 'Content-Type: application/json' -d '{""name"":""Kuro"",""age"":3}' 'localhost:8080/pets'
```

You should get this response:

```json
{
  ""age"": 3,
  ""id"": 1,
  ""name"": ""Kuro""
}
```

If you head over to the terminal where the server is running you can also see `elk`s built in logging:

```json
{
  ""level"": ""info"",
  ""msg"": ""pet rendered"",
  ""handler"": ""PetHandler"",
  ""method"": ""Create"",
  ""id"": 1
}
```

`elk` uses [zap](https://github.com/uber-go/zap) for logging. To learn more about it, have a look at its documentation.

### Relations

To illustrate more of `elk`s features, let’s extend our graph. Edit `ent/schema/user.go` and `ent/schema/pet.go`:

```go title=""ent/schema/pet.go""
// Edges of the Pet.
func (Pet) Edges() []ent.Edge {
    return []ent.Edge{
        edge.From(""owner"", User.Type).
            Ref(""pets"").
            Unique(),
    }
}

```

```go title=""ent/schema/user.go""
package schema

import (
	""entgo.io/ent""
	""entgo.io/ent/schema/edge""
	""entgo.io/ent/schema/field""
)

// User holds the schema definition for the User entity.
type User struct {
	ent.Schema
}

// Fields of the User.
func (User) Fields() []ent.Field {
	return []ent.Field{
		field.String(""name""),
		field.Int(""age""),
	}
}

// Edges of the User.
func (User) Edges() []ent.Edge {
	return []ent.Edge{
		edge.To(""pets"", Pet.Type),
	}
}

```

We have now created a One-To-Many relation between the Pet and User schemas: A pet belongs to a user, and a user can
have multiple pets.

Rerun the code generator:

```shell
go generate ./...
```

Do not forget to register the `UserHandler` on our router. Just add the following lines to `main.go`:

```diff
[...]
    r.Route(""/pets"", func(r chi.Router) {
        elk.NewPetHandler(c, l, v).Mount(r, elk.PetRoutes)
    })
+    // Create the user handler.
+    r.Route(""/users"", func(r chi.Router) {
+        elk.NewUserHandler(c, l, v).Mount(r, elk.UserRoutes)
+    })
    // Start listen to incoming requests.
    fmt.Println(""Server running"")
[...]
```

After restarting the server we can create a `User` that owns the previously created Pet named Kuro:

```shell
curl -X 'POST' -H 'Content-Type: application/json' -d '{""name"":""Elk"",""age"":30,""owner"":1}' 'localhost:8080/users'
```

The server returns the following response:

```json
{
  ""age"": 30,
  ""edges"": {},
  ""id"": 1,
  ""name"": ""Elk""
}
```

From the output we can see that the user has been created, but the edges are empty. `elk` does not include edges in its
output by default. You can configure `elk` to render edges using a feature called ""serialization groups"". Annotate your
schemas with the `elk.SchemaAnnotation`
and `elk.Annotation` structs. Edit `ent/schema/user.go` and add those:

```go
// Edges of the User.
func (User) Edges() []ent.Edge {
    return []ent.Edge{
        edge.To(""pets"", Pet.Type).
            Annotations(elk.Groups(""user"")),
    }
}

// Annotations of the User.
func (User) Annotations() []schema.Annotation {
    return []schema.Annotation{elk.ReadGroups(""user"")}
}

```

The `elk.Annotation`s added to the fields and edges tell elk to eager-load them and add them to the payload if the ""
user"" group is requested. The `elk.SchemaAnnotation` is used to make the read-operation of the `UserHandler` request ""
user"". Note, that any fields that do not have a serialization group attached are included by default. Edges, however,
are excluded, unless configured otherwise.

Next, let’s regenerate the code once again, and restart the server. You should now see the pets of a user rendered if
you read a resource:

```shell
curl 'localhost:8080/users/1'
```

```json
{
  ""age"": 30,
  ""edges"": {
    ""pets"": [
      {
        ""id"": 1,
        ""name"": ""Kuro"",
        ""age"": 3,
        ""edges"": {}
      }
    ]
  },
  ""id"": 1,
  ""name"": ""Elk""
}
```

### Request validation

Our current schemas allow to set a negative age for pets or users and we can create pets without an owner (as we did
with Kuro). Ent has built-in support for basic [validation](https://entgo.io/docs/schema-fields#validators). In some
cases you may want to validate requests made against your API before passing their payload to Ent. `elk`
uses [this](https://github.com/go-playground/validator) package to define validation rules and validate data. We can
create separate validation rules for Create and Update operations using `elk.Annotation`. In our example, let’s assume
that we want our Pet schema to only allow ages greater than zero and to disallow creating a pet without an owner.
Edit `ent/schema/pet.go`:

```go
// Fields of the Pet.
func (Pet) Fields() []ent.Field {
    return []ent.Field{
        field.String(""name""),
        field.Int(""age"").
            Positive().
            Annotations(
                elk.CreateValidation(""required,gt=0""),
                elk.UpdateValidation(""gt=0""),
            ),
    }
}

// Edges of the Pet.
func (Pet) Edges() []ent.Edge {
    return []ent.Edge{
        edge.From(""owner"", User.Type).
            Ref(""pets"").
            Unique().
            Required().
            Annotations(elk.Validation(""required"")),
    }
}
```

Next, regenerate the code and restart the server. To test our new validation rules, let’s try to create a pet with
invalid age and without an owner:

```shell
curl -X 'POST' -H 'Content-Type: application/json' -d '{""name"":""Bob"",""age"":-2}' 'localhost:8080/pets'
```

`elk` returns a detailed response that includes information about which validations failed:

```json
{
  ""code"": 400,
  ""status"": ""Bad Request"",
  ""errors"": {
    ""Age"": ""This value failed validation on 'gt:0'."",
    ""Owner"": ""This value is required.""
  }
}
```

Note the uppercase field names. The validator package uses the structs field name to generate its validation errors, but
you can simply override this, as stated in
the [example](https://github.com/go-playground/validator/blob/9a5bce32538f319bf69aebb3aca90d394bc6d0cb/_examples/struct-level/main.go#L37)
.

If you do not define any validation rules, `elk` will not include the validation-code in its generated output. `elk`s`
request validation is especially useful if you'd wanted to do cross-field-validation.

### Upcoming Features

We hope you agree that `elk` has some useful features already, but there are still many exciting things to come. The
next version of `elk` will include::

- Fully working flutter frontend to administrate your nodes
- Integration of Ent’s validation in the current request validator
- More transport formats (currently only JSON)

### Conclusion

This post has shown just a small part of what `elk` can do. To see some more examples of what you can do with it, head
over to the project’s README on GitHub. I hope that with `elk`-powered Ent, you and your fellow developers can automate
some repetitive tasks that go into building RESTful APIs and focus on more meaningful work.

`elk` is in an early stage of development, we welcome any suggestion or feedback and if you are willing to help we'd be
very glad. The [GitHub Issues](https://github.com/masseelch/elk/issues) is a wonderful place for you to reach out for
help, feedback, suggestions and contribution.

#### About the Author

_MasseElch is a software engineer from the windy, flat, north of Germany. When not hiking with his dog Kuro (who has his 
own Instagram channel :scream:) or playing hide-and-seek with his son, he drinks coffee and enjoys coding._

<!-- doc/website/blog/2021-11-1-sync-to-external-data-systems-using-hooks.md @ d056659140fa66973dd3753fead00a35de868ca3 -->
---
title: Sync Changes to External Data Systems using Ent Hooks
author: Ariel Mashraki
authorURL: https://github.com/a8m
authorImageURL: ""https://avatars0.githubusercontent.com/u/7413593""
authorTwitter: arielmashraki
image: https://entgo.io/images/assets/sync-hook/share.png
---

One of the common questions we get from the Ent community is how to synchronize objects or references between the
database backing an Ent application (e.g. MySQL or PostgreSQL) with external services. For example, users would like
to create or delete a record from within their CRM when a user is created or deleted in Ent, publish a message to a
[Pub/Sub system](https://en.wikipedia.org/wiki/Publish%E2%80%93subscribe_pattern) when an entity is updated, or verify
references to blobs in object storage such as AWS S3 or Google Cloud Storage.

Ensuring consistency between two separate data systems is not a simple task.  When we want to propagate, for example,
the deletion of a record in one system to another, there is no obvious way to guarantee that the two systems will end in
a synchronized state, since one of them may fail, and the network link between them may be slow or down. Having said
that, and especially with the prominence of microservices-architectures, these problems have become more common, and
distributed systems researchers have come up with patterns to solve them, such as the
[Saga Pattern](https://microservices.io/patterns/data/saga.html).

The application of these patterns is usually complex and difficult, and so in many cases architects do not go after a
""perfect"" design, and instead go after simpler solutions that involve either the acceptance of some inconsistency
between the systems or background reconciliation procedures.

In this post, we will not discuss how to solve distributed transactions or implement the Saga pattern with Ent.
Instead, we will limit our scope to study how to hook into Ent mutations before and after they occur, and run our
custom logic there.

### Propagating Mutations to External Systems

In our example, we are going to create a simple `User` schema with 2 immutable string fields, `""name""` and
`""avatar_url""`. Let's run the `ent init` command for creating a skeleton schema for our `User`:

```shell
go run entgo.io/ent/cmd/ent new User
```

Then, add the `name` and the `avatar_url` fields and run `go generate` to generate the assets.

```go title=""ent/schema/user.go""
type User struct {
	ent.Schema
}

func (User) Fields() []ent.Field {
	return []ent.Field{
		field.String(""name"").
			Immutable(),
		field.String(""avatar_url"").
			Immutable(),
	}
}
```

```shell
go generate ./ent
```

### The Problem

The `avatar_url` field defines a URL to an image in a bucket on our object storage (e.g. AWS S3). For the purpose of
this discussion  we want to make sure that:

- When a user is created, an image with the URL stored in `""avatar_url""` exists in our bucket.
- Orphan images are deleted from the bucket. This means that when a user is deleted from our system, its avatar image
  is deleted as well.

For interacting with blobs, we will use the [`gocloud.dev/blob`](https://gocloud.dev/howto/blob) package. This package
provides abstraction for reading, writing, deleting and listing blobs in a bucket. Similar to the `database/sql`
package, it allows interacting with variety of object storages with the same API by configuring its driver URL. 
For example:

```go
// Open an in-memory bucket. 
if bucket, err := blob.OpenBucket(ctx, ""mem://photos/""); err != nil {
	log.Fatal(""failed opening in-memory bucket:"", err)
}

// Open an S3 bucket named photos.
if bucket, err := blob.OpenBucket(ctx, ""s3://photos""); err != nil {
	log.Fatal(""failed opening s3 bucket:"", err)
}

// Open a bucket named photos in Google Cloud Storage.
if bucket, err := blob.OpenBucket(ctx, ""gs://my-bucket""); err != nil {
	log.Fatal(""failed opening gs bucket:"", err)
}
```

### Schema Hooks

[Hooks](https://entgo.io/docs/hooks) are a powerful feature of Ent that allows adding custom logic before and after
operations that mutate the graph.

Hooks can be either defined dynamically using `client.Use` (called ""Runtime Hooks""), or explicitly on the schema
(called ""Schema Hooks"") as follows:

```go
// Hooks of the User.
func (User) Hooks() []ent.Hook {
	return []ent.Hook{
		EnsureImageExists(),
		DeleteOrphans(),
	}
}
```

As you can imagine, the `EnsureImageExists` hook will be responsible for ensuring that when a user is created, their
avatar URL exists in the bucket, and the `DeleteOrphans` will ensure that orphan images are deleted. Let's start
writing them.

```go title=""ent/schema/hooks.go""
func EnsureImageExists() ent.Hook {
	hk := func(next ent.Mutator) ent.Mutator {
		return hook.UserFunc(func(ctx context.Context, m *ent.UserMutation) (ent.Value, error) {
			avatarURL, exists := m.AvatarURL()
			if !exists {
				return nil, errors.New(""avatar field is missing"")
			}
			// TODO:
			// 1. Verify that ""avatarURL"" points to a real object in the bucket.
			// 2. Otherwise, fail.
			return next.Mutate(ctx, m)
		})
	}
	// Limit the hook only to ""Create"" operations.
	return hook.On(hk, ent.OpCreate)
}

func DeleteOrphans() ent.Hook {
	hk := func(next ent.Mutator) ent.Mutator {
		return hook.UserFunc(func(ctx context.Context, m *ent.UserMutation) (ent.Value, error) {
			id, exists := m.ID()
			if !exists {
				return nil, errors.New(""id field is missing"")
			}
			// TODO:
			// 1. Get the AvatarURL field of the deleted user.
			// 2. Cascade the deletion to object storage.
			return next.Mutate(ctx, m)
		})
	}
	// Limit the hook only to ""DeleteOne"" operations.
	return hook.On(hk, ent.OpDeleteOne)
}
```

Now, you may ask yourself, _how do we access the blob client from the mutations hooks?_ You are going to find out in
the next section.

### Injecting Dependencies

The [entc.Dependency](https://entgo.io/docs/code-gen/#external-dependencies) option allows extending the generated
builders with external dependencies as struct fields, and provides options for injecting them on client initialization.

To inject a `blob.Bucket` to be available inside our hooks, we can follow the tutorial about external dependencies in
[the website](https://entgo.io/docs/code-gen/#external-dependencies), and define the
[`gocloud.dev/blob.Bucket`](https://pkg.go.dev/gocloud.dev/blob#Bucket) as a dependency.

```go title=""ent/entc.go"" {3-6}
func main() {
	opts := []entc.Option{
		entc.Dependency(
			entc.DependencyName(""Bucket""),
			entc.DependencyType(&blob.Bucket{}),
		),
	}
	if err := entc.Generate(""./schema"", &gen.Config{}, opts...); err != nil {
		log.Fatalf(""running ent codegen: %v"", err)
	}
}
```

Next, re-run code generation:

```shell
go generate ./ent
```

We can now access the Bucket API from all generated builders. Let's finish the implementations of the above hooks.

```go title=""ent/schema/hooks.go""
// EnsureImageExists ensures the avatar_url points
// to a real object in the bucket.
func EnsureImageExists() ent.Hook {
	hk := func(next ent.Mutator) ent.Mutator {
		return hook.UserFunc(func(ctx context.Context, m *ent.UserMutation) (ent.Value, error) {
			avatarURL, exists := m.AvatarURL()
			if !exists {
				return nil, errors.New(""avatar field is missing"")
			}
			switch exists, err := m.Bucket.Exists(ctx, avatarURL); {
			case err != nil:
				return nil, fmt.Errorf(""check key existence: %w"", err)
			case !exists:
				return nil, fmt.Errorf(""key %q does not exist in the bucket"", avatarURL)
			default:
				return next.Mutate(ctx, m)
			}
		})
	}
	return hook.On(hk, ent.OpCreate)
}

// DeleteOrphans cascades the user deletion to the bucket.
// Hence, when a user is deleted, its avatar image is deleted
// as well.
func DeleteOrphans() ent.Hook {
	hk := func(next ent.Mutator) ent.Mutator {
		return hook.UserFunc(func(ctx context.Context, m *ent.UserMutation) (ent.Value, error) {
			id, exists := m.ID()
			if !exists {
				return nil, errors.New(""id field is missing"")
			}
			u, err := m.Client().User.Get(ctx, id)
			if err != nil {
				return nil, fmt.Errorf(""getting deleted user: %w"", err)
			}
			if err := m.Bucket.Delete(ctx, u.AvatarURL); err != nil {
				return nil, fmt.Errorf(""deleting user avatar from bucket: %w"", err)
			}
			return next.Mutate(ctx, m)
		})
	}
	return hook.On(hk, ent.OpDeleteOne)
}
```

Now, it's time to test our hooks! Let's write a testable example that verifies that our 2 hooks work as expected.

```go
package main

import (
	""context""
	""fmt""
	""log""

	""github.com/a8m/ent-sync-example/ent""
	_ ""github.com/a8m/ent-sync-example/ent/runtime""

	""entgo.io/ent/dialect""
	_ ""github.com/mattn/go-sqlite3""
	""gocloud.dev/blob""
	_ ""gocloud.dev/blob/memblob""
)

func Example_SyncCreate() {
	ctx := context.Background()
	// Open an in-memory bucket.
	bucket, err := blob.OpenBucket(ctx, ""mem://photos/"")
	if err != nil {
		log.Fatal(""failed opening bucket:"", err)
	}
	client, err := ent.Open(
		dialect.SQLite,
		""file:ent?mode=memory&cache=shared&_fk=1"",
		// Inject the blob.Bucket on client initialization.
		ent.Bucket(bucket),
	)
	if err != nil {
		log.Fatal(""failed opening connection to sqlite:"", err)
	}
	defer client.Close()
	if err := client.Schema.Create(ctx); err != nil {
		log.Fatal(""failed creating schema resources:"", err)
	}
	if err := client.User.Create().SetName(""a8m"").SetAvatarURL(""a8m.png"").Exec(ctx); err == nil {
		log.Fatal(""expect user creation to fail because the image does not exist in the bucket"")
	}
	if err := bucket.WriteAll(ctx, ""a8m.png"", []byte{255, 255, 255}, nil); err != nil {
		log.Fatalf(""failed uploading image to the bucket: %v"", err)
	}
	fmt.Printf(""%q\n"", keys(ctx, bucket))

	// User creation should pass as image was uploaded to the bucket.
	u := client.User.Create().SetName(""a8m"").SetAvatarURL(""a8m.png"").SaveX(ctx)

	// Deleting a user, should delete also its image from the bucket.
	client.User.DeleteOne(u).ExecX(ctx)
	fmt.Printf(""%q\n"", keys(ctx, bucket))

	// Output:
	// [""a8m.png""]
	// []
}
```

### Wrapping Up

Great! We have configured Ent to extend our generated code and inject the `blob.Bucket` as an 
[External Dependency](https://entgo.io/docs/code-gen#external-dependencies). Next, we defined two mutation hooks and
used the `blob.Bucket` API to ensure our product constraints are satisfied.

The code for this example is available at [github.com/a8m/ent-sync-example](https://github.com/a8m/ent-sync-example).

:::note For more Ent news and updates:

- Subscribe to our [Newsletter](https://entgo.substack.com/)
- Follow us on [Twitter](https://twitter.com/entgo_io)
- Join us on #ent on the [Gophers Slack](https://entgo.io/docs/slack)
- Join us on the [Ent Discord Server](https://discord.gg/qZmPgTE6RX)

:::

