	return []ent.Field{
		field.Time(""created_at"").
			Immutable().
			Default(time.Now),..."", ""path"": ""doc/md/schema-mixin.md"", ""retrieval_provenance"": {""blob_sha"": ""a4fe8cc92088fd154c0106f73eb9cd049be53ed4"", ""discovery_source"": ""base_sha_tree"", ""excluded_artifact_paths"": 8, ""generator_pool_policy"": ""base_sha_broad_bounded_doc_pool_v2"", ""max_generator_doc_chars_per_file"": 1500, ""max_generator_doc_files"": 12, ""method"": ""base_sha_tree_documentation_discovery_v2"", ""path"": ""doc/md/schema-mixin.md"", ""selection_policy"": ""prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity"", ""selection_rank"": 9, ""selection_score"": [45, 4, 5, 3, ""doc/md/schema-mixin.md""], ""tree_discovery_succeeded"": true, ""tree_ref"": ""9442826ba628d9fe309e91cc3331c695c32b1db6"", ""truncated"": false, ""truncated_excerpt"": true, ""used_docs_changed_files"": false}, ""source_ref"": ""9442826ba628d9fe309e91cc3331c695c32b1db6""}, {""blob_sha"": ""ff2abfe79fd643496dffddf1ab85a5f69930f2bf"", ""excerpt"": ""---
id: schema-views
title: Views
slug: /schema-views
---

import Tabs from '@theme/Tabs';
import TabItem from '@theme/TabItem';

Ent supports working with database views. Unlike regular Ent types (schemas), which are usually backed by tables, views
act as ""virtual tables"" and their data results from a query. The following examples demonstrate how to define a `VIEW`
in Ent. For more details on the different options, follow the rest of the guide.

<Tabs>
<TabItem value=""Builder Definition"">

```go title=""ent/schema/user.go""
// CleanUser represents a user without its PII field.
type CleanUser struct {
	ent.View
}

// Annotations of the CleanUser.
func (CleanUser) Annotations() []schema.Annotation {
	return []schema.Annotation{
		entsql.ViewFor(dialect.Postgres, func(s *sql.Selector) {
			s.Select(""name"", ""public_info"").From(sql.Table(""users""))
		}),
	}
}

// Fields of the CleanUser.
func (CleanUser) Fields() []ent.Field {
	return []ent.Field{
		field.String(""name""),
		field.String(""public_info""),
	}
}
```
</TabItem>
