-//	DROP INDEX index_name [ON table_name]
-func (d *DropIndexBuilder) Query() (string, []any) {
-	d.WriteString(""DROP INDEX "")
-	d.Ident(d.name)
-	if d.table != """" {
-		d.WriteString("" ON "")
-		d.Ident(d.table)
-	}
-	return d.String(), nil
-}
